    let relative = path.strip_prefix(root).ok()?.to_str()?;
    if !normal(relative) {
        return None;
    }
    let row = affected_row(relative)?;
    Some((|| {
        let actual = current(&row)?;
        if row["current"]["length"].as_u64() == Some(length as u64)
            && row["current"]["sha256"] == expected
