        }
        match &declaration.kind {
            TypeDeclarationKind::Record { fields } => {
                for f in fields {
                    census.field(f)?;
                }
            }
            TypeDeclarationKind::Variant { cases } => {
                for case in cases {
                    census.name(&case.name)?;
                    census.name(&case.stable_id)?;
                    for f in &case.fields {
                        census.field(f)?;
                    }
