    fn derive_with_work(
        caller: &Program,
        authored: &'a BTreeMap<&'a str, AuthoredDeclaration<'a>>,
        programs: &'a [Program],
        remaining: &mut usize,
        ledger: Option<&std::rc::Rc<ledger::Ledger>>,
    ) -> Result<Self, Vec<Diagnostic>> {
