        let mut count = 0usize;
        visit(
            caller,
            authored,
            programs,
            &mut frames,
            remaining,
            |_, _, _| {
                count = count.checked_add(1usize).ok_or_else(refusal)?;
                Ok(())
            },
        )?;
        if count == 0 {
            return Ok(Self {
                entries: Vec::new(),
                owners: None,
