            != Some(super::digest(&super::canonical(before)).as_str())
    {
        return Err("v8 authenticated old519");
    }
    let mut expanded = v8_carriers(before, page)?;
    expanded["schema"] = SCHEMA_V7.into();
    expand_v7(before, policy, &expanded)
}

