            + size_of::<&Rc<Budget>>()
            + 4 * size_of::<&Rc<Budget>>()
            + 2 * size_of::<&Budget>()
            + 2 * size_of::<&Budget>()
            + 2 * size_of::<usize>()
            + 2 * size_of::<&Cell<bool>>()
            + 2 * size_of::<bool>();
