        // stage get has its own actual/formal receiver and Option return.
        let receipt_fields = 4 * size_of::<&Cell<usize>>()
            + 2 * size_of::<usize>()
            + 2 * size_of::<&Cell<Stage>>()
            + size_of::<Stage>();
